mapper.select:
select c.command_id, c.tree_id, c.category_node_id, coalesce(( select group_concat(distinct tbn.node_name order by tbn.node_id separator '、') from biz_tree_category_bind tcb inner join biz_tree_node tbn on tbn.node_id = tcb.node_id and tbn.del_flag = '0' where tcb.business_type = 'commandConfig' and tcb.business_id = c.command_id and tcb.del_flag = '0' ), n.node_name) as category_node_name, c.command_code, c.command_name, c.command_type, c.command_template, c.status, c.create_time, c.remark from biz_command_config c left join biz_tree_node n on n.node_id = c.category_node_id and n.del_flag = '0'
c.del_flag = '0'
and c.command_code like concat('%', #{bo.commandCode}, '%')
and c.command_name like concat('%', #{bo.commandName}, '%')
and c.command_type = #{bo.commandType}
and c.tree_id = #{bo.treeId}
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'commandConfig' and fcb.business_id = c.command_id and fcb.del_flag = '0' and fcb.node_id in
#{categoryNodeId}
)
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'commandConfig' and fcb.business_id = c.command_id and fcb.del_flag = '0' and fcb.node_id = #{bo.categoryNodeId} )
and c.status = #{bo.status}
order by c.create_time desc, c.command_id desc

select c.command_id, c.tree_id, c.category_node_id, coalesce(( select group_concat(distinct tbn.node_name order by tbn.node_id separator '、') from biz_tree_category_bind tcb inner join biz_tree_node tbn on tbn.node_id = tcb.node_id and tbn.del_flag = '0' where tcb.business_type = 'commandConfig' and tcb.business_id = c.command_id and tcb.del_flag = '0' ), n.node_name) as category_node_name, c.command_code, c.command_name, c.command_type, c.command_template, c.status, c.create_time, c.remark from biz_command_config c left join biz_tree_node n on n.node_id = c.category_node_id and n.del_flag = '0'
c.del_flag = '0'
and c.command_code like concat('%', #{bo.commandCode}, '%')
and c.command_name like concat('%', #{bo.commandName}, '%')
and c.command_type = #{bo.commandType}
and c.tree_id = #{bo.treeId}
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'commandConfig' and fcb.business_id = c.command_id and fcb.del_flag = '0' and fcb.node_id in
#{categoryNodeId}
)
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'commandConfig' and fcb.business_id = c.command_id and fcb.del_flag = '0' and fcb.node_id = #{bo.categoryNodeId} )
and c.status = #{bo.status}
order by c.create_time desc, c.command_id desc
